78	// Every declared pack's task declarations, from one recursive tree listing.
79	// `paths` is the flat list of blob paths the tree API returned.
80	export function taskDeclarationPaths(paths, config) {
81	  const dirs = declaredPackDirs(config);
82	  const found = [];
83	  for (const path of paths ?? []) {
84	    const m = TASK_PATH_RE.exec(path);
85	    if (!m) continue;
