7:<link rel="icon" href="./favicon.svg" type="image/svg+xml">
8:<style>
9:  /* Light is the base palette; the dark steps are their own selected values under
10:     both the OS setting and an explicit toggle, never an automatic inversion. */
11:  :root {
12:    color-scheme: light;
13:    --plane:      #f9f9f7;
14:    --surface:    #fcfcfb;
15:    --ink:        #0b0b0b;
16:    --ink-2:      #52514e;
17:    --muted:      #898781;
18:    --rule:       #e1e0d9;
19:    --border:     rgba(11,11,11,0.10);
20:
21:    --good:     #0ca30c;
22:    --warning:  #fab219;
23:    --serious:  #ec835a;
24:    --critical: #d03b3b;
25:
26:    --s-blue:   #2a78d6;
27:    --s-orange: #eb6834;
28:    --s-aqua:   #1baf7a;
29:    --s-yellow: #eda100;
30:    --s-violet: #4a3aa7;
31:  }
32:  @media (prefers-color-scheme: dark) {
33:    :root:not([data-theme="light"]) {
34:      color-scheme: dark;
35:      --plane:   #0d0d0d;
36:      --surface: #1a1a19;
37:      --ink:     #ffffff;
38:      --ink-2:   #c3c2b7;
39:      --muted:   #898781;
40:      --rule:    #2c2c2a;
41:      --border:  rgba(255,255,255,0.10);
42:      --s-blue:   #3987e5;
43:      --s-orange: #d95926;
44:      --s-aqua:   #199e70;
45:      --s-yellow: #c98500;
46:      --s-violet: #9085e9;
47:    }
48:  }
49:  :root[data-theme="dark"] {
50:    color-scheme: dark;
51:    --plane:   #0d0d0d;
52:    --surface: #1a1a19;
53:    --ink:     #ffffff;
54:    --ink-2:   #c3c2b7;
55:    --muted:   #898781;
56:    --rule:    #2c2c2a;
57:    --border:  rgba(255,255,255,0.10);
58:    --s-blue:   #3987e5;
59:    --s-orange: #d95926;
60:    --s-aqua:   #199e70;
61:    --s-yellow: #c98500;
62:    --s-violet: #9085e9;
63:  }
64:
65:  * { box-sizing: border-box; }
66:  body {
67:    margin: 0;
68:    background: var(--plane);
69:    color: var(--ink);
70:    font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
71:  }
72:  a { color: var(--s-blue); }
73:  h1 { font-size: 17px; margin: 0; letter-spacing: -0.01em; }
74:  h2 { font-size: 13px; margin: 0 0 10px; color: var(--ink-2); font-weight: 600;
75:       text-transform: uppercase; letter-spacing: 0.06em; }
76:  .wrap { max-width: 1180px; margin: 0 auto; padding: 18px 20px 64px; }
77:
78:  /* --- controls --- */
79:  /* `topbar`, not `bar`: `.bar` is the outcome mini-chart below, and a header
80:     sharing that name inherits its 7px×108px geometry. */
81:  header.topbar {
82:    position: sticky; top: 0; z-index: 5;
83:    background: var(--surface);
84:    border-bottom: 1px solid var(--rule);
85:  }
86:  .topbar-in { max-width: 1180px; margin: 0 auto; padding: 12px 20px;
87:               display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
88:  .grow { flex: 1 1 auto; }
89:  input, button, select {
90:    font: inherit; color: var(--ink); background: var(--surface);
91:    border: 1px solid var(--border); border-radius: 7px; padding: 6px 9px;
92:  }
93:  input { min-width: 190px; }
94:  select { max-width: 260px; }
95:  button { cursor: pointer; }
96:  button:hover { border-color: var(--muted); }
97:  button[disabled] { opacity: .5; cursor: default; }
98:  button.primary { background: var(--s-blue); border-color: var(--s-blue); color: #fff; font-weight: 600; }
99:  .hint { color: var(--muted); font-size: 12px; }
100:  .authbox { display: inline-flex; align-items: center; gap: 8px; }
101:  .avatar { border-radius: 50%; display: block; }
102:
103:  /* --- stat tiles: the headline numbers, no chart needed --- */
104:  .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
105:           gap: 10px; margin-bottom: 22px; }
106:  .tile { background: var(--surface); border: 1px solid var(--border);
107:          border-radius: 10px; padding: 12px 14px; }
108:  .tile .v { font-size: 25px; line-height: 1.15; }
109:  .tile .k { font-size: 12px; color: var(--ink-2); margin-top: 2px; }
110:
111:  /* --- panels & tables --- */
112:  section { margin-bottom: 26px; }
113:  .panel { background: var(--surface); border: 1px solid var(--border);
114:           border-radius: 10px; overflow: hidden; }
115:  table { width: 100%; border-collapse: collapse; }
116:  th { text-align: left; font-size: 11px; text-transform: uppercase;
117:       letter-spacing: 0.05em; color: var(--muted); font-weight: 600;
118:       padding: 9px 12px; border-bottom: 1px solid var(--rule); white-space: nowrap; }
119:  td { padding: 9px 12px; border-bottom: 1px solid var(--rule); vertical-align: top; }
120:  tr:last-child td { border-bottom: 0; }
121:  tbody tr:hover { background: color-mix(in srgb, var(--ink) 4%, transparent); }
122:  .num { font-variant-numeric: tabular-nums; }
123:  /* Hyphenated declaration values (`merged-pr`, `daily-2h`) are single tokens to a
124:     reader and must not break at their hyphen. */
125:  .nw { white-space: nowrap; }
126:  .scroll { overflow-x: auto; }
127:  .name { font-weight: 600; }
128:  .sub { color: var(--muted); font-size: 12px; }
129:
130:  /* --- chips: state is identity, so it always carries its own label text --- */

